import{_ as t,o as l,c as o,a2 as a}from"./chunks/framework.B7YvHKtj.js";const u=JSON.parse('{"title":"Netflix AI Subtitle Translator - 控制面板 (Popup UI) 详细使用指南","description":"","frontmatter":{},"headers":[],"relativePath":"zh/docs/guide/popup.md","filePath":"zh/docs/guide/popup.md"}'),r={name:"zh/docs/guide/popup.md"};function i(n,e,s,d,c,g){return l(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="netflix-ai-subtitle-translator-控制面板-popup-ui-详细使用指南" tabindex="-1">Netflix AI Subtitle Translator - 控制面板 (Popup UI) 详细使用指南 <a class="header-anchor" href="#netflix-ai-subtitle-translator-控制面板-popup-ui-详细使用指南" aria-label="Permalink to &quot;Netflix AI Subtitle Translator - 控制面板 (Popup UI) 详细使用指南&quot;">​</a></h1><p>本文档全面介绍 Netflix AI Subtitle Translator 扩展控制面板（Popup 弹窗）中各项功能、UI 控件的用途、推荐配置以及调优技巧。</p><hr><h2 id="目录" tabindex="-1">目录 <a class="header-anchor" href="#目录" aria-label="Permalink to &quot;目录&quot;">​</a></h2><ol><li><a href="#1-顶部状态栏与主开关">顶部状态栏与主开关</a></li><li><a href="#2-ai-服务提供商配置">AI 服务提供商配置 (Ollama 与 OpenRouter)</a></li><li><a href="#3-语言与字幕显示偏好">语言与字幕显示偏好</a></li><li><a href="#4-影视记忆与角色表管理">影视记忆与角色表管理 (Show Context)</a></li><li><a href="#5-双模型流水线性能调优">双模型流水线性能调优 (Pipeline Settings)</a></li><li><a href="#6-字幕视觉样式与时间轴微调">字幕视觉样式与时间轴微调</a></li><li><a href="#7-快速连通性与模型测试">快速连通性与模型测试 (Quick Test)</a></li><li><a href="#8-常见问题与调优建议">常见问题与调优建议</a></li></ol><hr><h2 id="_1-顶部状态栏与主开关" tabindex="-1">1. 顶部状态栏与主开关 <a class="header-anchor" href="#_1-顶部状态栏与主开关" aria-label="Permalink to &quot;1. 顶部状态栏与主开关&quot;">​</a></h2><p><img src="https://img.shields.io/badge/UI-Header-e50914" alt="Header"></p><h3 id="_1-1-全局启用开关-enabled-toggle" tabindex="-1">1.1 全局启用开关 (<code>#enabled-toggle</code>) <a class="header-anchor" href="#_1-1-全局启用开关-enabled-toggle" aria-label="Permalink to &quot;1.1 全局启用开关 (`#enabled-toggle`)&quot;">​</a></h3><ul><li><strong>位置</strong>：右上角切换开关。</li><li><strong>功能</strong>：全局启用或禁用 AI 字幕翻译。</li><li><strong>说明</strong>： <ul><li>开启（绿色）：在 Netflix 播放页面自动监听字幕流并实时渲染翻译。</li><li>关闭：隐藏 AI 字幕并暂停所有后台模型推理，同时恢复 Netflix 原始字幕层。</li><li><strong>快捷键</strong>：播放页面随时按下 <strong><code>Alt + T</code></strong> 可实现相同开关效果。</li></ul></li></ul><h3 id="_1-2-ko-fi-赞助按钮-☕" tabindex="-1">1.2 Ko-fi 赞助按钮 (<code>☕</code>) <a class="header-anchor" href="#_1-2-ko-fi-赞助按钮-☕" aria-label="Permalink to &quot;1.2 Ko-fi 赞助按钮 (`☕`)&quot;">​</a></h3><ul><li><strong>位置</strong>：顶部右上角与弹窗底部。</li><li><strong>功能</strong>：点击在新标签页打开作者的 <a href="https://ko-fi.com/sfbb49898" target="_blank" rel="noreferrer">Ko-fi 赞助页面</a>。</li></ul><h3 id="_1-3-服务连接状态卡片-status-card" tabindex="-1">1.3 服务连接状态卡片 (<code>#status-card</code>) <a class="header-anchor" href="#_1-3-服务连接状态卡片-status-card" aria-label="Permalink to &quot;1.3 服务连接状态卡片 (`#status-card`)&quot;">​</a></h3><ul><li><strong>状态指示灯</strong>： <ul><li>🟢 <strong>绿色 (Connected)</strong>：服务连通正常，模型列表已成功加载。</li><li>🟡 <strong>黄色 (Checking / Warning)</strong>：正在检测连通性或未配置有效模型。</li><li>🔴 <strong>红色 (Disconnected / Error)</strong>：无法连接到本地 Ollama 或云端 API 认证失败。</li></ul></li><li><strong>刷新按钮 (<code>🔄</code>)</strong>：手动重新向当前服务提供商发送探测请求，重新拉取最新可用的模型列表。</li></ul><hr><h2 id="_2-ai-服务提供商配置" tabindex="-1">2. AI 服务提供商配置 <a class="header-anchor" href="#_2-ai-服务提供商配置" aria-label="Permalink to &quot;2. AI 服务提供商配置&quot;">​</a></h2><p>在 <strong>🤖 AI Service Provider (<code>#ai-provider</code>)</strong> 下拉框中，您可以自由切换两种推理模式：</p><h3 id="_2-1-本地部署-ollama-local-privacy-first" tabindex="-1">2.1 本地部署：Ollama (Local / Privacy-first) <a class="header-anchor" href="#_2-1-本地部署-ollama-local-privacy-first" aria-label="Permalink to &quot;2.1 本地部署：Ollama (Local / Privacy-first)&quot;">​</a></h3><p>适合拥有独立显卡（如 NVIDIA RTX 3060 及以上）、注重隐私且无需消耗云端 Token 的用户。</p><table tabindex="0"><thead><tr><th style="text-align:left;">控件名称</th><th style="text-align:left;">元素 ID</th><th style="text-align:left;">推荐值 / 示例</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Ollama API URL</strong></td><td style="text-align:left;"><code>#ollama-host</code></td><td style="text-align:left;"><code>http://localhost:11434</code></td><td style="text-align:left;">本地或局域网 Ollama 服务的监听地址。点击 <strong>Connect</strong> 按钮测试连接并更新模型列表。</td></tr><tr><td style="text-align:left;"><strong>翻译模型 (Translation Model)</strong></td><td style="text-align:left;"><code>#translation-model</code></td><td style="text-align:left;"><code>translategemma:4b</code></td><td style="text-align:left;">负责快速批量翻译（默认预翻译 50 句）。系统会自动从本地 <code>ollama list</code> 中读取所有已拉取的模型。</td></tr><tr><td style="text-align:left;"><strong>监督模型 (Supervisor Model)</strong></td><td style="text-align:left;"><code>#supervisor-model</code></td><td style="text-align:left;"><code>gemma4:e4b</code></td><td style="text-align:left;">负责剧集背景预热、术语统一审校与人名记忆提炼。建议选择指令理解能力更强的模型。</td></tr></tbody></table><blockquote><p><strong>提示</strong>：如果在 Linux/macOS 下遇到跨域错误，启动 Ollama 时可添加环境变量 <code>OLLAMA_ORIGINS=&quot;*&quot; ollama serve</code>。</p></blockquote><hr><h3 id="_2-2-云端平台-openrouter-cloud-multi-model" tabindex="-1">2.2 云端平台：OpenRouter (Cloud / Multi-model) <a class="header-anchor" href="#_2-2-云端平台-openrouter-cloud-multi-model" aria-label="Permalink to &quot;2.2 云端平台：OpenRouter (Cloud / Multi-model)&quot;">​</a></h3><p>适合轻薄本、核显用户，或者追求前沿大模型极高质量翻译（如 DeepSeek V3、Gemini 2.5 Pro、Claude 3.5 Haiku 等）的用户。</p><table tabindex="0"><thead><tr><th style="text-align:left;">控件名称</th><th style="text-align:left;">元素 ID</th><th style="text-align:left;">推荐值 / 示例</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>OpenRouter API Key</strong></td><td style="text-align:left;"><code>#openrouter-api-key</code></td><td style="text-align:left;"><code>sk-or-v1-...</code></td><td style="text-align:left;">您的 OpenRouter API 密钥。可点击右侧 <strong>👁️</strong> 图标明文查看或隐藏，点击 <strong>Connect</strong> 进行鉴权。密钥安全保存在本地浏览器存储中，绝不上传到任何第三方。</td></tr><tr><td style="text-align:left;"><strong>OpenRouter 翻译模型</strong></td><td style="text-align:left;"><code>#openrouter-translation-model</code></td><td style="text-align:left;"><code>deepseek/deepseek-chat</code> 或 <code>google/gemini-2.5-flash</code></td><td style="text-align:left;">下拉框内置了高性价比推荐模型列表，并在连接后动态拉取 OpenRouter 的完整模型库。</td></tr><tr><td style="text-align:left;"><strong>自定义翻译模型 ID</strong></td><td style="text-align:left;"><code>#openrouter-custom-translation-model</code></td><td style="text-align:left;">如 <code>qwen/qwen-2.5-72b-instruct</code></td><td style="text-align:left;">在下拉框选择「✏️ 自定义输入模型 ID」时出现，支持填入 OpenRouter 支持的任意模型标识符。</td></tr><tr><td style="text-align:left;"><strong>OpenRouter 监督模型</strong></td><td style="text-align:left;"><code>#openrouter-supervisor-model</code></td><td style="text-align:left;"><code>google/gemini-2.5-flash</code> 或 <code>deepseek/deepseek-chat</code></td><td style="text-align:left;">负责多批次审阅与人物角色表维护。云端并发度高、处理长文本能力极佳。</td></tr><tr><td style="text-align:left;"><strong>自定义监督模型 ID</strong></td><td style="text-align:left;"><code>#openrouter-custom-supervisor-model</code></td><td style="text-align:left;">如 <code>google/gemini-2.5-pro</code></td><td style="text-align:left;">在下拉框选择「✏️ 自定义输入模型 ID」时出现。</td></tr></tbody></table><hr><h3 id="_2-3-监督模型全局开关-enable-supervisor" tabindex="-1">2.3 监督模型全局开关 (<code>#enable-supervisor</code>) <a class="header-anchor" href="#_2-3-监督模型全局开关-enable-supervisor" aria-label="Permalink to &quot;2.3 监督模型全局开关 (`#enable-supervisor`)&quot;">​</a></h3><ul><li><strong>功能</strong>：是否启用第二模型进行影视背景维护与人名一致性校对。</li><li><strong>开启建议</strong>： <ul><li>看剧情片、动漫（人名昵称复杂）、连续剧时<strong>强烈建议开启</strong>，能彻底解决角色前几集叫“小翔”、后几集变“硝子”等称呼混乱问题。</li></ul></li><li><strong>关闭建议</strong>： <ul><li>本地显存不足（如只有 4G~6G VRAM）时，关闭可避免双模型在显存中进出置换；</li><li>使用 OpenRouter 时若想进一步节省 Token 费用，也可将其关闭。</li></ul></li></ul><hr><h2 id="_3-语言与字幕显示偏好" tabindex="-1">3. 语言与字幕显示偏好 <a class="header-anchor" href="#_3-语言与字幕显示偏好" aria-label="Permalink to &quot;3. 语言与字幕显示偏好&quot;">​</a></h2><h3 id="_3-1-界面语言-ui-language" tabindex="-1">3.1 界面语言 (<code>#ui-language</code>) <a class="header-anchor" href="#_3-1-界面语言-ui-language" aria-label="Permalink to &quot;3.1 界面语言 (`#ui-language`)&quot;">​</a></h3><ul><li>支持 <strong>English</strong>、<strong>中文 (Chinese)</strong>、<strong>日本語 (Japanese)</strong>、<strong>한국어 (Korean)</strong>。</li><li>切换后立刻实时更新插件界面的全部文本与提示信息。</li></ul><h3 id="_3-2-翻译目标语言-target-language" tabindex="-1">3.2 翻译目标语言 (<code>#target-language</code>) <a class="header-anchor" href="#_3-2-翻译目标语言-target-language" aria-label="Permalink to &quot;3.2 翻译目标语言 (`#target-language`)&quot;">​</a></h3><ul><li>支持 15 种主流语言（简体中文、繁體中文、English、日本語、한국어、Español 等）。</li><li><strong>语言隔离机制</strong>：切换目标语言时，插件会自动切换至对应语言的影视记忆与角色字典（例如《Stranger Things》的中文记忆与日文记忆独立存储，互不干扰）。</li></ul><h3 id="_3-3-字幕显示模式-display-mode" tabindex="-1">3.3 字幕显示模式 (<code>#display-mode</code>) <a class="header-anchor" href="#_3-3-字幕显示模式-display-mode" aria-label="Permalink to &quot;3.3 字幕显示模式 (`#display-mode`)&quot;">​</a></h3><ol><li><strong>双语模式 (Bilingual)</strong>：上方显示翻译语言，下方显示原声字幕（默认推荐）。</li><li><strong>仅显示翻译 (Translation Only)</strong>：画面只呈现 AI 翻译结果，纯净观影。</li><li><strong>仅显示原声 (Original Only)</strong>：只显示经过插件排版优化的原声音轨字幕。</li></ol><h3 id="_3-4-隐藏-netflix-原生字幕-hide-native-subs" tabindex="-1">3.4 隐藏 Netflix 原生字幕 (<code>#hide-native-subs</code>) <a class="header-anchor" href="#_3-4-隐藏-netflix-原生字幕-hide-native-subs" aria-label="Permalink to &quot;3.4 隐藏 Netflix 原生字幕 (`#hide-native-subs`)&quot;">​</a></h3><ul><li><strong>默认状态</strong>：开启（推荐）。</li><li><strong>原理</strong>：通过 CSS 将 Netflix 原生自带的字幕渲染层透明化，防止原生单语字幕与 AI 双语字幕在屏幕中央产生重影或重叠，同时完全不影响底层网络字幕流的捕获。</li></ul><hr><h2 id="_4-影视记忆与角色表管理" tabindex="-1">4. 影视记忆与角色表管理 <a class="header-anchor" href="#_4-影视记忆与角色表管理" aria-label="Permalink to &quot;4. 影视记忆与角色表管理&quot;">​</a></h2><p>在 <strong>🎬 Show Context &amp; Supervisor Memory</strong> 卡片中，展示了当前播放影片的上下文积累情况：</p><ul><li><strong>作品标题 (<code>#show-title</code>)</strong>：自动提取正在播放的影视剧名称与季度信息。</li><li><strong>记忆状态标签 (<code>#memory-badge</code>)</strong>： <ul><li><code>Pending</code>：等待播放开始。</li><li><code>Ready</code>：背景预热完成，角色表建立完毕。</li><li><code>Auditing</code>：监督模型正在后台审阅新字幕批次。</li></ul></li><li><strong>剧情梗概 (<code>#show-synopsis</code>)</strong>：由监督模型在背景预热阶段自动生成的剧集背景简介。</li><li><strong>角色与术语标签栏 (<code>#glossary-tags</code>)</strong>： <ul><li>实时展示当前剧集已收录的专有名词与角色别名映射（如 <code>Shou-chan ➔ 西宫硝子</code>）。</li><li>每个标签右侧带有 <code>×</code> 按钮，点击可立即移除该映射。</li></ul></li><li><strong>手动添加/纠正词条 (<code>#input-term-orig</code> ➔ <code>#input-term-trans</code>)</strong>： <ul><li>如发现某位主角名字翻译不符合个人喜好，可在输入框填入原文名字（如 <code>Eleven</code>）与目标翻译（如 <code>小十一</code>），点击 <strong>Save</strong>，即可强制锁定全局翻译规则。</li></ul></li><li><strong>重置记忆按钮 (<code>#btn-reset-context</code>)</strong>： <ul><li>清空当前作品累积的角色表与背景记忆，并在下一次播放时重新触发 Warmup（预热）。</li></ul></li></ul><hr><h2 id="_5-双模型流水线性能调优" tabindex="-1">5. 双模型流水线性能调优 <a class="header-anchor" href="#_5-双模型流水线性能调优" aria-label="Permalink to &quot;5. 双模型流水线性能调优&quot;">​</a></h2><p>插件内置了针对 <strong>Ollama（本地算力）</strong> 与 <strong>OpenRouter（云端算力）</strong> 的独立预设参数，并支持用户自定义拖拽微调：</p><h3 id="_5-1-动态-cue-批量与缓冲参数" tabindex="-1">5.1 动态 Cue 批量与缓冲参数 <a class="header-anchor" href="#_5-1-动态-cue-批量与缓冲参数" aria-label="Permalink to &quot;5.1 动态 Cue 批量与缓冲参数&quot;">​</a></h3><h4 id="_1-最小请求句数-min-cue-min-translate-cues" tabindex="-1">① 最小请求句数 (<code>min_cue</code> / <code>#min-translate-cues</code>) <a class="header-anchor" href="#_1-最小请求句数-min-cue-min-translate-cues" aria-label="Permalink to &quot;① 最小请求句数 (`min_cue` / `#min-translate-cues`)&quot;">​</a></h4><ul><li><strong>滑块范围</strong>：1 ~ 20 句（默认：1 句）。</li><li><strong>机制原理</strong>：当缓冲区字幕达到该数量时，即可触发一次模型推理下发。设置为 1 可确保任何新出现的零散字幕立即开始翻译。</li><li><strong>空仓急冲 (Seek Burst)</strong>：当用户拖动进度条跳转到未翻译的片段时，系统自动采用 <code>Math.max(min_cue, 6)</code> 下发首批请求，确保 400ms 内瞬间上屏首句字幕，同时立刻构建起最少 6 句的初始安全缓冲，彻底消除卡顿。</li><li><strong>片尾免截断 (Tail Exemption)</strong>：在影视剧末尾或原始字幕轨尾部时，系统会自动解除 <code>min_cue</code> 门槛限制。即使剩余未翻译的台词不足设定句数，也会全量下发翻译，彻底避免片尾最后几句台词被遗漏或截断。</li></ul><h4 id="_2-单次最大下发句数-max-cue-max-translate-cues" tabindex="-1">② 单次最大下发句数 (<code>max_cue</code> / <code>#max-translate-cues</code>) <a class="header-anchor" href="#_2-单次最大下发句数-max-cue-max-translate-cues" aria-label="Permalink to &quot;② 单次最大下发句数 (`max_cue` / `#max-translate-cues`)&quot;">​</a></h4><ul><li><strong>滑块范围</strong>：10 ~ 150 句。</li><li><strong>预设配置</strong>： <ul><li><strong>Ollama 预设</strong>：30 句（防止本地轻量模型单次长文本输出丢行或显存占用过高）。</li><li><strong>OpenRouter 预设</strong>：100 句（充分利用云端大模型的高并发与长上下文处理能力，减少网络往返耗时）。</li></ul></li></ul><h4 id="_3-自动补充阈值-refill-threshold-refill-threshold" tabindex="-1">③ 自动补充阈值 (<code>refill_threshold</code> / <code>#refill-threshold</code>) <a class="header-anchor" href="#_3-自动补充阈值-refill-threshold-refill-threshold" aria-label="Permalink to &quot;③ 自动补充阈值 (`refill_threshold` / `#refill-threshold`)&quot;">​</a></h4><ul><li><strong>滑块范围</strong>：2 ~ 40 句。</li><li><strong>预设配置</strong>：Ollama 预设 10 句；OpenRouter 预设 20 句。</li><li><strong>说明</strong>：当播放器中剩余未播放的预翻译字幕低于该阈值时，后台静默自动拉取下一批字幕，确保在持续观影过程中永远不会出现字幕“断供”。</li></ul><h3 id="_5-2-监督模型审校批次大小-reviewbatchsize-review-batch-size" tabindex="-1">5.2 监督模型审校批次大小 (<code>reviewBatchSize</code> / <code>#review-batch-size</code>) <a class="header-anchor" href="#_5-2-监督模型审校批次大小-reviewbatchsize-review-batch-size" aria-label="Permalink to &quot;5.2 监督模型审校批次大小 (`reviewBatchSize` / `#review-batch-size`)&quot;">​</a></h3><ul><li><strong>滑块范围</strong>：2 ~ 40 句。</li><li><strong>预设配置</strong>：Ollama 预设 8 句；OpenRouter 预设 20 句。</li><li><strong>说明</strong>：监督模型每次在单个 Prompt 中集中比对的对话数量。云端模型可适当调大（如 20 句），效率更高且上下文关联性更强。</li></ul><hr><h2 id="_6-字幕视觉样式与时间轴微调" tabindex="-1">6. 字幕视觉样式与时间轴微调 <a class="header-anchor" href="#_6-字幕视觉样式与时间轴微调" aria-label="Permalink to &quot;6. 字幕视觉样式与时间轴微调&quot;">​</a></h2><h3 id="_6-1-视觉样式调整" tabindex="-1">6.1 视觉样式调整 <a class="header-anchor" href="#_6-1-视觉样式调整" aria-label="Permalink to &quot;6.1 视觉样式调整&quot;">​</a></h3><ul><li><strong>字幕字体大小 (<code>#font-size</code>)</strong>：范围 18px ~ 44px（默认 26px）。</li><li><strong>字幕背景透明度 (<code>#bg-opacity</code>)</strong>：范围 0% ~ 100%（默认 0% 全透明）。在画面背景非常花哨时，可适当调至 30%~50% 提高对比度。</li><li><strong>底边距 (<code>#sub-offset</code>)</strong>：范围 40px ~ 180px（默认 80px），微调字幕距离屏幕底部的悬浮高度，避免遮挡原生进度条。</li><li><strong>原文字幕缩小显示 (<code>#show-original-smaller</code>)</strong>：开启后双语模式中的原声语言按 75% 字号显示，突出主翻译语言。</li><li><strong>毛玻璃效果底框 (<code>#enable-glass-effect</code>)</strong>：启用半透明高斯模糊背景与细腻边框，呈现高端磨砂质感。</li><li><strong>字幕淡入淡出动画 (<code>#enable-animation</code>)</strong>： <ul><li><strong>默认关闭</strong>：字幕瞬间切换，0 延迟、0 闪烁，字字清晰干脆。</li><li><strong>开启</strong>：呈现温和平滑的渐隐渐现视觉动效。</li></ul></li></ul><h3 id="_6-2-时间轴偏移校准-sync-offset-val" tabindex="-1">6.2 时间轴偏移校准 (<code>#sync-offset-val</code>) <a class="header-anchor" href="#_6-2-时间轴偏移校准-sync-offset-val" aria-label="Permalink to &quot;6.2 时间轴偏移校准 (`#sync-offset-val`)&quot;">​</a></h3><p>当遇到含广告套餐中插广告、或者片源音画不同步时：</p><ul><li>点击 <strong>Earlier (+0.5s)</strong>：字幕提前 0.5 秒呈现（快捷键：<code>[</code> 或 <code>Alt + [</code>）。</li><li>点击 <strong>Later (-0.5s)</strong>：字幕延后 0.5 秒呈现（快捷键：<code>]</code> 或 <code>Alt + ]</code>）。</li><li>点击 <strong>Reset</strong>：重置偏移量为 0.0 秒（快捷键：<code>\\</code> 或 <code>Alt + \\</code>）。</li><li><strong>DOM 原生字幕自动校准 (<code>#enable-dom-sync</code>)</strong>： <ul><li>默认关闭。当开启时，插件会比对 Netflix 屏幕可见的原生字幕字符变化来微调时间，常规播放时无需开启（播放器内核 API 已自动高精对齐）。</li></ul></li></ul><hr><h2 id="_7-快速连通性与模型测试" tabindex="-1">7. 快速连通性与模型测试 <a class="header-anchor" href="#_7-快速连通性与模型测试" aria-label="Permalink to &quot;7. 快速连通性与模型测试&quot;">​</a></h2><p>在 <strong>Quick Test</strong> 区域，您可以在不打开 Netflix 播放页面的情况下，直接验证当前模型配置是否工作正常：</p><ol><li>在文本框输入任意测试对话（如 <code>Hello! The weather is fantastic today.</code>）。</li><li>点击 <strong>Test</strong> 按钮。</li><li><strong>第一阶段</strong>：翻译模型下发并返回目标语言译文，展示本次翻译耗时（毫秒）。</li><li><strong>第二阶段</strong>：如果启用了监督模型，系统紧接着模拟监督审阅流程，并在下方展示监督模型修正结果与耗时。</li></ol><hr><h2 id="_8-常见问题与调优建议" tabindex="-1">8. 常见问题与调优建议 <a class="header-anchor" href="#_8-常见问题与调优建议" aria-label="Permalink to &quot;8. 常见问题与调优建议&quot;">​</a></h2><h3 id="q1-本地-ollama-响应较慢导致字幕跟不上" tabindex="-1">Q1: 本地 Ollama 响应较慢导致字幕跟不上？ <a class="header-anchor" href="#q1-本地-ollama-响应较慢导致字幕跟不上" aria-label="Permalink to &quot;Q1: 本地 Ollama 响应较慢导致字幕跟不上？&quot;">​</a></h3><ol><li><strong>换用高速度小模型</strong>：翻译模型推荐 <code>translategemma:4b</code> 或 <code>qwen2.5:3b</code>。</li><li><strong>调大提前量与阈值</strong>：将 <code>max_cue</code> 调整至 40，将 <code>Auto-Refill Threshold</code> 调整至 15，让模型更早地在后台完成预处理。</li><li><strong>关闭监督模型</strong>：在显存或 CPU 负载较高时，关闭 <code>#enable-supervisor</code>。</li></ol><h3 id="q2-想使用云端顶尖模型-如何兼顾速度与成本" tabindex="-1">Q2: 想使用云端顶尖模型，如何兼顾速度与成本？ <a class="header-anchor" href="#q2-想使用云端顶尖模型-如何兼顾速度与成本" aria-label="Permalink to &quot;Q2: 想使用云端顶尖模型，如何兼顾速度与成本？&quot;">​</a></h3><ul><li>服务提供商选择 <strong>OpenRouter</strong>： <ul><li><strong>翻译模型</strong>：选择 <code>deepseek/deepseek-chat</code>（极其便宜且翻译质量顶尖）或 <code>google/gemini-2.5-flash</code>（速度极快）。</li><li><strong>监督模型</strong>：选择 <code>google/gemini-2.5-flash</code>。</li><li><strong>Pipeline 设置</strong>：直接使用系统默认预设（<code>max_cue</code> = 100，<code>review_batch</code> = 20），网络吞吐最高，每集观影成本微乎其微。</li></ul></li></ul>',71)])])}const f=t(r,[["render",i]]);export{u as __pageData,f as default};
